static void dfs(struct TreeNode *node, int *out, int *size) {
  if (node == NULL) return;
  dfs(node->left, out, size);
  dfs(node->right, out, size);
  out[(*size)++] = node->val;
}

int *postorderTraversal(struct TreeNode *root, int *returnSize) {
  int *out = (int *)malloc(sizeof(int) * 101);
  *returnSize = 0;
  dfs(root, out, returnSize);
  return out;
}

class Solution {
  void dfs(TreeNode *node, vector<int> &out) {
    if (!node) return;
    dfs(node->left, out);
    dfs(node->right, out);
    out.push_back(node->val);
  }

public:
  vector<int> postorderTraversal(TreeNode *root) {
    vector<int> out;
    dfs(root, out);
    return out;
  }
};

func postorderTraversal(root *TreeNode) []int {
	out := []int{}
	var dfs func(node *TreeNode)
	dfs = func(node *TreeNode) {
		if node == nil {
			return
		}
		dfs(node.Left)
		dfs(node.Right)
		out = append(out, node.Val)
	}
	dfs(root)
	return out
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private void dfs(TreeNode node, List<Integer> out) {
    if (node == null) {
      return;
    }
    dfs(node.left, out);
    dfs(node.right, out);
    out.add(node.val);
  }

  public List<Integer> postorderTraversal(TreeNode root) {
    List<Integer> out = new ArrayList<>();
    dfs(root, out);
    return out;
  }
}

class Solution:
    def postorderTraversal(self, root: Optional[TreeNode]) -> List[int]:
        out: List[int] = []

        def dfs(node):
            if node is None:
                return
            dfs(node.left)
            dfs(node.right)
            out.append(node.val)

        dfs(root)
        return out

impl Solution {
  pub fn postorder_traversal(root: Option<Box<TreeNode>>) -> Vec<i32> {
    fn dfs(node: &Option<Box<TreeNode>>, out: &mut Vec<i32>) {
      if let Some(n) = node {
        dfs(&n.left, out);
        dfs(&n.right, out);
        out.push(n.val);
      }
    }

    let mut out = Vec::new();
    dfs(&root, &mut out);
    out
  }
}

const postorderTraversal = (root: TreeNode | null): number[] => {
  const out: number[] = [];
  const dfs = (node: TreeNode | null): void => {
    if (node === null) return;
    dfs(node.left);
    dfs(node.right);
    out.push(node.val);
  };
  dfs(root);
  return out;
};
